use anyhow::{Context,Result};
use maintain_protocol::{EngineRequest,EngineResponse,IpcEnvelope,PROTOCOL_VERSION};
use std::path::PathBuf;
use tokio::io::{AsyncBufReadExt,AsyncWriteExt,BufReader};
use tracing::{error,info};
#[tokio::main]async fn main()->Result<()>{tracing_subscriber::fmt().with_env_filter(std::env::var("RUST_LOG").unwrap_or_else(|_|"info".into())).init();let data=data_dir()?;std::fs::create_dir_all(&data)?;let db=data.join("maintain-native.sqlite3");maintain_persistence::open_database(&db).with_context(||format!("failed to initialize {}",db.display()))?;#[cfg(unix)]run_unix(data.join("engine.sock")).await?;#[cfg(windows)]run_windows().await?;Ok(())}
fn data_dir()->Result<PathBuf>{if let Some(p)=std::env::var_os("MAINTAIN_DATA_DIR"){return Ok(PathBuf::from(p));}Ok(dirs::data_local_dir().context("cannot locate local data directory")?.join("DMJ Group").join("MAINTAIN AI Native"))}
fn respond(r:EngineRequest)->EngineResponse{match r{EngineRequest::Ping=>EngineResponse::Pong{protocol_version:PROTOCOL_VERSION,engine:"MAINTAIN AI Native Rust Engine".into()},EngineRequest::GetSystemStatus=>EngineResponse::SystemStatus{ready:true,database:"sqlite".into()}}}
#[cfg(unix)]async fn run_unix(path:PathBuf)->Result<()>{use tokio::net::UnixListener;use std::os::unix::fs::PermissionsExt;if path.exists(){std::fs::remove_file(&path)?;}let listener=UnixListener::bind(&path)?;std::fs::set_permissions(&path,std::fs::Permissions::from_mode(0o600))?;info!(socket=%path.display(),"local IPC ready");loop{let(stream,_)=listener.accept().await?;tokio::spawn(async move{let result=async{let(reader,mut writer)=stream.into_split();let mut lines=BufReader::new(reader).lines();while let Some(line)=lines.next_line().await?{if line.len()>65536{return Err(anyhow::anyhow!("IPC request exceeds 64 KiB"));}let req:IpcEnvelope<EngineRequest>=serde_json::from_str(&line)?;if req.protocol_version!=PROTOCOL_VERSION{return Err(anyhow::anyhow!("unsupported IPC protocol version"));}let out=IpcEnvelope::new(req.request_id,respond(req.message));writer.write_all(serde_json::to_string(&out)?.as_bytes()).await?;writer.write_all(b"\n").await?;}Ok::<(),anyhow::Error>(())}.await;if let Err(e)=result{error!(error=%e,"IPC connection ended");}});}}
#[cfg(windows)]async fn run_windows()->Result<()>{use tokio::net::windows::named_pipe::ServerOptions;let name=r"\\.\pipe\maintain-ai-native";info!(pipe=name,"local IPC ready");loop{let server=ServerOptions::new().create(name)?;server.connect().await?;tokio::spawn(async move{let mut stream=server;let result=async{let mut reader=BufReader::new(&mut stream);let mut line=String::new();while reader.read_line(&mut line).await?>0{if line.len()>65536{return Err(anyhow::anyhow!("IPC request exceeds 64 KiB"));}let req:IpcEnvelope<EngineRequest>=serde_json::from_str(&line)?;if req.protocol_version!=PROTOCOL_VERSION{return Err(anyhow::anyhow!("unsupported IPC protocol version"));}let out=IpcEnvelope::new(req.request_id,respond(req.message));reader.get_mut().write_all(&serde_json::to_vec(&out)?).await?;reader.get_mut().write_all(b"\n").await?;line.clear();}Ok::<(),anyhow::Error>(())}.await;if let Err(e)=result{error!(error=%e,"named pipe client ended");}});}}
